create table if not exists public.player_drill_assignments (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams(id) on delete cascade, player_id uuid not null, assigned_by uuid not null default auth.uid(), drill_title text not null, drill_description text, due_date date not null default ((now() at time zone 'utc')::date), status text not null default 'assigned' check (status in ('assigned','completed','missed')), completion_note text, completed_at timestamptz, created_at timestamptz not null default now()); alter table public.player_drill_assignments enable row level security; create policy pda_select on public.player_drill_assignments for select using (is_team_member(team_id)); create policy pda_insert on public.player_drill_assignments for insert with check (assigned_by=auth.uid() and is_team_owner(team_id)); create policy pda_update on public.player_drill_assignments for update using (is_team_member(team_id)) with check (is_team_member(team_id)); create policy pda_delete on public.player_drill_assignments for delete using (is_team_owner(team_id));